_showAlert(msgHdr, title, body, numNewMessages) {
  const folder = msgHdr.folder;

  const alertsService = Cc["@mozilla.org/system-alerts-service;1"].getService(
    Ci.nsIAlertsService
  );
  const alert = new AlertNotification({
    name: folder.generateMessageURI(msgHdr.messageKey),
    // Don't add an icon on macOS, the app icon is already shown.
    imageURL:
      AppConstants.platform == "macosx"
        ? ""
        : "chrome://branding/content/icon48.png",
    title,
    text: body,
    textClickable: true,
  });

  if (numNewMessages == 1) {
    alert.actions = lazy.enabledActions.filter(action =>
      action.isValidFor(msgHdr)
    );
  }
  alertsService.showAlertWithCallbacks(alert, {
    QueryInterface: ChromeUtils.generateQI(["nsIAlertCallbacks"]),
    onAlertClick(action) {
      if (action) {
        Glean.mail.notificationUsedActions[action.action].add(1);
        availableActions
          .find(a => a.action == action.action)
          .runAction(msgHdr);
        return;
      }
      // Display the associated message when an alert is clicked.
      lazy.MailUtils.displayMessageInFolderTab(msgHdr, true);
    },
    onAlertFinished() {},
  });
